import { useState, useRef, useEffect, useCallback, MutableRefObject } from "react";

const PLAYER_IMG = "data:image/png;base64,";
const LOGO_IMG   = "data:image/png;base64,";
const SC_IMG     = "data:image/png;base64,";

const CW = 600;
const CH = 840;
const POSITIONS = ["GK", "DEF", "MID", "FWD"];

function useImage(src: string): [MutableRefObject<HTMLImageElement | null>, boolean] {
  const ref = useRef<HTMLImageElement | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    const img = new window.Image() as HTMLImageElement;
    img.onload = () => { ref.current = img; setReady(true); };
    img.src = src;
  }, [src]);
  return [ref, ready];
}

export default function LouFuszGenerator() {
  const [firstName, setFirstName] = useState<string>("JACK");
  const [lastName,  setLastName]  = useState<string>("SANDER");
  const [number,    setNumber]    = useState<string>("9");
  const [position,  setPosition]  = useState<string>("MID");
  const [gradYear,  setGradYear]  = useState<string>("2035");
  const [customSrc, setCustomSrc] = useState<string | null>(null);

  const canvasRef  = useRef<HTMLCanvasElement | null>(null);
  const customRef  = useRef<HTMLImageElement | null>(null);
  const [playerRef, playerReady] = useImage(PLAYER_IMG);
  const [logoRef,   logoReady]   = useImage(LOGO_IMG);
  const [scRef,     scReady]     = useImage(SC_IMG);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !playerReady || !logoReady || !scReady) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, CW, CH);

    const NAVY:  [number,number,number] = [10, 22, 40];
    const ROYAL: [number,number,number] = [28, 58, 120];
    const GOLD:  [number,number,number] = [201, 168, 76];
    const GOLD2: [number,number,number] = [224, 188, 94];
    const DARK:  [number,number,number] = [8, 18, 32];

    const rgb  = (c: [number,number,number]) => `rgb(${c[0]},${c[1]},${c[2]})`;
    const rgba = (c: [number,number,number], a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;

    // ── Background ──────────────────────────────────────────────────
    ctx.fillStyle = rgb(NAVY);
    ctx.fillRect(0, 0, CW, CH);

    const H_HDR = 101;
    for (let r = H_HDR; r < CH - 150; r++) {
      const t = (r - H_HDR) / (CH - 150 - H_HDR);
      const p = 0.5 - Math.abs(t - 0.5);
      ctx.fillStyle = `rgb(${Math.round(10 + p * 35)},${Math.round(22 + p * 45)},${Math.round(40 + p * 80)})`;
      ctx.fillRect(0, r, CW, 1);
    }

    ctx.save();
    for (let x = -CH; x < CW + CH; x += 22) {
      ctx.strokeStyle = "rgba(201,168,76,0.11)";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x + CH, CH); ctx.stroke();
    }
    ctx.restore();

    ctx.fillStyle = rgba(ROYAL, 0.78);
    ctx.fillRect(0, 0, 18, CH);
    ctx.fillRect(CW - 18, 0, 18, CH);
    ctx.fillStyle = rgb(GOLD);
    ctx.fillRect(0, 0, 2, CH);
    ctx.fillRect(CW - 2, 0, 2, CH);

    // ── Player photo ─────────────────────────────────────────────────
    const imgSrc = customRef.current ?? playerRef.current;
    if (imgSrc) {
      const scaleH = Math.round(CH * 0.86);
      const scaleW = Math.round((imgSrc.naturalWidth / imgSrc.naturalHeight) * scaleH);
      const ox = (CW - scaleW) / 2;
      const oy = CH - scaleH - 30;
      ctx.drawImage(imgSrc, ox, oy, scaleW, scaleH);
    }

    const tg = ctx.createLinearGradient(0, H_HDR, 0, H_HDR + 160);
    tg.addColorStop(0, "rgba(10,22,40,0.86)");
    tg.addColorStop(1, "rgba(10,22,40,0)");
    ctx.fillStyle = tg;
    ctx.fillRect(0, H_HDR, CW, 160);

    const bg = ctx.createLinearGradient(0, CH - 200, 0, CH);
    bg.addColorStop(0, "rgba(10,22,40,0)");
    bg.addColorStop(1, "rgba(10,22,40,1)");
    ctx.fillStyle = bg;
    ctx.fillRect(0, CH - 200, CW, 200);

    // ── Header ───────────────────────────────────────────────────────
    const H = 95;
    ctx.fillStyle = rgb(DARK);
    ctx.fillRect(0, 0, CW, H);
    for (let c = 0; c < 200; c++) {
      ctx.fillStyle = rgba(ROYAL, (80 * (1 - c / 200)) / 255);
      ctx.fillRect(CW - c, 0, 1, H);
    }

    ctx.save();
    ctx.globalAlpha = 0.09;
    ctx.fillStyle = rgb(GOLD);
    ctx.font = "bold 110px Arial";
    ctx.textAlign = "right";
    ctx.fillText(number || "0", CW - 60, 90);
    ctx.restore();

    ctx.textAlign = "left";
    ctx.font = "bold 13px Arial";
    ctx.fillStyle = rgb(GOLD);
    ctx.fillText("LOU FUSZ ATHLETIC", 18, 22);

    ctx.font = "11px Arial";
    ctx.fillStyle = rgba(GOLD, 0.62);
    ctx.fillText("2016B  ·  BLUE STAR", 18, 40);

    const fullName = `${firstName} ${lastName}`.trim().toUpperCase() || "PLAYER NAME";
    ctx.font = "bold 36px Arial";
    ctx.fillStyle = "#ffffff";
    ctx.fillText(fullName, 18, 76);
    const nameWidth = Math.min(ctx.measureText(fullName).width + 10, CW - 120);
    ctx.fillStyle = rgb(GOLD);
    ctx.fillRect(18, 82, nameWidth, 3);

    ctx.fillStyle = rgb(ROYAL);
    ctx.fillRect(0, H - 3, CW, 3);
    ctx.fillStyle = rgb(GOLD);
    ctx.fillRect(0, H, CW, 6);

    // ── Jersey badge ─────────────────────────────────────────────────
    const bx = CW - 88, by = 8, bs = 72;
    const chamfer = (pts: [number, number][]) => {
      ctx.beginPath();
      pts.forEach(([x, y], i) => i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y));
      ctx.closePath();
    };
    ctx.fillStyle = rgb(GOLD);
    chamfer([[bx+12,by],[bx+bs,by],[bx+bs,by+bs],[bx,by+bs],[bx,by+12]]);
    ctx.fill();
    ctx.fillStyle = rgb(GOLD2);
    chamfer([[bx+14,by+2],[bx+bs-2,by+2],[bx+bs-2,by+bs-2],[bx+2,by+bs-2],[bx+2,by+14]]);
    ctx.fill();

    ctx.fillStyle = rgb(DARK);
    ctx.font = "bold 20px Arial";
    const hw = ctx.measureText("#").width;
    ctx.font = "bold 44px Arial";
    const nw = ctx.measureText(number || "0").width;
    const tw = hw + 2 + nw;
    const sx = bx + (bs - tw) / 2;
    const cy = by + bs / 2;
    ctx.font = "bold 20px Arial";
    ctx.fillText("#", sx, cy + 4);
    ctx.font = "bold 44px Arial";
    ctx.fillText(number || "0", sx + hw + 2, cy + 16);

    // ── Sash ─────────────────────────────────────────────────────────
    const SY = CH - 170, SH = 74;
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = i % 2 === 0 ? "rgba(28,58,120,0.9)" : "rgba(8,18,32,0.9)";
      ctx.fillRect(0, SY - 22 + i * 5, CW, 2);
    }
    const sg = ctx.createLinearGradient(0, SY, 0, SY + SH);
    sg.addColorStop(0, rgb(GOLD2));
    sg.addColorStop(1, rgb(GOLD));
    ctx.fillStyle = sg;
    ctx.fillRect(0, SY, CW, SH);
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = i % 2 === 0 ? "rgba(28,58,120,0.9)" : "rgba(8,18,32,0.9)";
      ctx.fillRect(0, SY + SH + i * 5, CW, 2);
    }

    if (logoRef.current) {
      let lw = CW - 160;
      let lh = Math.round(logoRef.current.naturalHeight * (lw / logoRef.current.naturalWidth));
      if (lh > SH - 6) { lh = SH - 6; lw = Math.round(logoRef.current.naturalWidth * (lh / logoRef.current.naturalHeight)); }
      ctx.drawImage(logoRef.current, (CW - lw) / 2, SY + (SH - lh) / 2, lw, lh);
    }

    if (scRef.current) {
      const ss = SH - 6;
      const sw = Math.round(scRef.current.naturalWidth * (ss / scRef.current.naturalHeight));
      ctx.drawImage(scRef.current, 22, SY + (SH - ss) / 2, sw, ss);
      ctx.drawImage(scRef.current, CW - 22 - sw, SY + (SH - ss) / 2, sw, ss);
    }

    // ── Pills ─────────────────────────────────────────────────────────
    const PY = SY + SH + 18;
    const pills: [string, string][] = [["POS", position || "—"], ["GRAD", gradYear || "—"], ["CLUB", "LFA"]];
    const pw = 108, ph = 46, gap = 14;
    const tot = pills.length * pw + (pills.length - 1) * gap;
    let px = (CW - tot) / 2;

    for (const [lbl, val] of pills) {
      ctx.fillStyle = rgba(ROYAL, 0.55);
      roundRect(ctx, px, PY, pw, ph, 8);
      ctx.fill();
      ctx.strokeStyle = rgb(GOLD);
      ctx.lineWidth = 1;
      roundRect(ctx, px, PY, pw, ph, 8);
      ctx.stroke();
      ctx.fillStyle = rgba(GOLD, 0.86);
      ctx.font = "500 10px Arial";
      ctx.textAlign = "center";
      ctx.fillText(lbl, px + pw / 2, PY + 16);
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 17px Arial";
      ctx.fillText(val, px + pw / 2, PY + 36);
      px += pw + gap;
    }
    ctx.textAlign = "left";
  }, [firstName, lastName, number, position, gradYear, playerReady, logoReady, scReady, customSrc]);

  function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  useEffect(() => { draw(); }, [draw]);

  function handlePhoto(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new window.Image() as HTMLImageElement;
      img.onload = () => { customRef.current = img; setCustomSrc(ev.target?.result as string); };
      img.src = ev.target?.result as string;
    };
    reader.readAsDataURL(file);
  }

  function download() {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const a = document.createElement("a");
    a.download = `${(firstName + lastName).replace(/\s/g, "_") || "card"}.png`;
    a.href = canvas.toDataURL("image/png");
    a.click();
  }

  const GOLD_HEX = "#c9a84c";

  const inp: React.CSSProperties = {
    width: "100%", padding: "8px 10px", borderRadius: 6,
    border: "0.5px solid rgba(201,168,76,0.4)",
    background: "rgba(10,22,40,0.8)", color: "#fff",
    fontSize: 13, outline: "none", marginTop: 4, boxSizing: "border-box",
  };
  const lbl: React.CSSProperties = {
    fontSize: 10, letterSpacing: "1.5px", color: "rgba(201,168,76,0.7)",
    textTransform: "uppercase", display: "block",
  };

  return (
    <div style={{ background: "#06111f", minHeight: "100vh", padding: "20px 16px", fontFamily: "Arial,sans-serif", color: "#fff" }}>
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div style={{ fontSize: 11, letterSpacing: 3, color: GOLD_HEX, textTransform: "uppercase", marginBottom: 4 }}>
          Lou Fusz Athletic · 2016B Blue Star
        </div>
        <div style={{ fontSize: 20, fontWeight: 700 }}>Player Card Generator</div>
      </div>

      <div style={{ display: "flex", gap: 24, alignItems: "flex-start", justifyContent: "center", flexWrap: "wrap" }}>

        {/* Form */}
        <div style={{ width: 240, background: "rgba(10,22,40,0.7)", border: "0.5px solid rgba(201,168,76,0.25)", borderRadius: 12, padding: 20 }}>
          <div style={{ fontSize: 11, letterSpacing: 2, color: GOLD_HEX, textTransform: "uppercase", marginBottom: 14, fontWeight: 700 }}>
            Player Details
          </div>

          <div style={{ marginBottom: 12 }}>
            <label style={lbl}>Photo</label>
            <label style={{ display: "block", marginTop: 4, border: "1.5px dashed rgba(201,168,76,0.35)", borderRadius: 8, padding: "14px 10px", textAlign: "center", cursor: "pointer", color: "rgba(201,168,76,0.55)", fontSize: 12, background: "rgba(10,22,40,0.5)" }}>
              {customSrc ? "📷 Photo loaded" : "⬆ Upload photo"}
              <input type="file" accept="image/*" onChange={handlePhoto} style={{ display: "none" }} />
            </label>
            {customSrc && (
              <button onClick={() => { customRef.current = null; setCustomSrc(null); }}
                style={{ marginTop: 6, fontSize: 10, color: "rgba(201,168,76,0.6)", background: "none", border: "none", cursor: "pointer", padding: 0 }}>
                ↩ Use default photo
              </button>
            )}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 12 }}>
            <div>
              <label style={lbl}>First Name</label>
              <input style={inp} value={firstName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFirstName(e.target.value.toUpperCase())} placeholder="FIRST" />
            </div>
            <div>
              <label style={lbl}>Last Name</label>
              <input style={inp} value={lastName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setLastName(e.target.value.toUpperCase())} placeholder="LAST" />
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 12 }}>
            <div>
              <label style={lbl}>Jersey #</label>
              <input style={inp} value={number} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNumber(e.target.value)} placeholder="9" maxLength={2} />
            </div>
            <div>
              <label style={lbl}>Grad Year</label>
              <input style={inp} value={gradYear} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setGradYear(e.target.value)} placeholder="2035" maxLength={4} />
            </div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <label style={lbl}>Position</label>
            <select style={{ ...inp, cursor: "pointer" }} value={position} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setPosition(e.target.value)}>
              {POSITIONS.map((p) => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          <button onClick={download}
            style={{ width: "100%", padding: "11px 0", background: GOLD_HEX, color: "#080a10", border: "none", borderRadius: 8, fontWeight: 700, fontSize: 13, letterSpacing: 1, cursor: "pointer", textTransform: "uppercase" }}>
            ⬇ Download Card
          </button>
        </div>

        {/* Preview */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div style={{ fontSize: 11, letterSpacing: 2, color: GOLD_HEX, textTransform: "uppercase", marginBottom: 10, fontWeight: 700 }}>
            Live Preview
          </div>
          <div style={{ borderRadius: 14, overflow: "hidden", boxShadow: "0 12px 48px rgba(0,0,0,0.7)" }}>
            <canvas ref={canvasRef} width={CW} height={CH} style={{ display: "block", width: 300, height: 420 }} />
          </div>
          <div style={{ fontSize: 11, color: "rgba(255,255,255,0.35)", marginTop: 8 }}>
            Updates as you type · Full resolution download
          </div>
        </div>

      </div>
    </div>
  );
}
